package com.clothingstore;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.math.BigDecimal; import java.security.SecureRandom; import java.time.Instant; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1") @CrossOrigin(origins="${app.cors-origin}") public class StoreController {
  private final ProductRepository products; private final StoreOrderRepository orders;
  StoreController(ProductRepository products, StoreOrderRepository orders){this.products=products;this.orders=orders;}
  record ProductResponse(Long id,String name,String slug,String category,BigDecimal price,String imageUrl){} record CheckoutLine(@Min(1) Long productId,@Min(1) Integer quantity){} record CheckoutRequest(@Email @NotBlank String email,@NotBlank String phone,@NotBlank String fullName,@NotBlank String address,@NotBlank String city,@NotBlank String postalCode,@NotEmpty List<@Valid CheckoutLine> items){} record CheckoutResponse(String orderNumber,String status,BigDecimal total){}
  @GetMapping("/products") public List<ProductResponse> products(){return products.findByActiveTrue().stream().map(p->new ProductResponse(p.getId(),p.getName(),p.getSlug(),p.getCategory(),p.getPrice(),p.getImageUrl())).toList();}
  @PostMapping("/checkout") @ResponseStatus(HttpStatus.CREATED) @Transactional public CheckoutResponse checkout(@RequestBody @Valid CheckoutRequest request){ StoreOrder order=new StoreOrder(); order.setOrderNumber("LX-"+(100000+new SecureRandom().nextInt(900000))); order.setEmail(request.email());order.setPhone(request.phone());order.setFullName(request.fullName());order.setAddressLine(request.address());order.setCity(request.city());order.setPostalCode(request.postalCode());order.setPaymentMethod("COD");order.setOrderStatus("PENDING"); BigDecimal total=BigDecimal.ZERO; for(CheckoutLine line:request.items()){Product product=products.findByIdAndActiveTrue(line.productId()).orElseThrow(()->new IllegalArgumentException("A requested product is unavailable."));OrderItem item=new OrderItem();item.setProduct(product);item.setProductName(product.getName());item.setUnitPrice(product.getPrice());item.setQuantity(line.quantity());item.setLineTotal(product.getPrice().multiply(BigDecimal.valueOf(line.quantity())));order.addItem(item);total=total.add(item.getLineTotal());} BigDecimal shipping=total.compareTo(BigDecimal.valueOf(150))>=0?BigDecimal.ZERO:BigDecimal.valueOf(12);order.setTotalAmount(total.add(shipping));orders.save(order);return new CheckoutResponse(order.getOrderNumber(),order.getOrderStatus(),order.getTotalAmount()); }
  @GetMapping("/health") public Map<String,Object> health(){return Map.of("status","UP","timestamp",Instant.now());}
}
